terms=['Inmt','Fmo2','Mgp','Cxcl12','Lepr','Kitl','Ebf3','Ebf1','Lpl','Lung','Bone','Adipose','tissue']
for fn in sorted(glob.glob('MOESM*.xlsx')):
    try:
        wb=openpyxl.load_workbook(fn, read_only=True, data_only=True)
    except Exception as e: print(fn,e); continue
    print('\\nFILE',fn,'size',os.path.getsize(fn),'sheets',wb.sheetnames)
    for ws in wb.worksheets:
        hits=[]
        for i,row in enumerate(ws.iter_rows(values_only=True), start=1):
            if i>5000: break
            vals=[str(v) for v in row if v is not None]
            line='\\t'.join(vals)
            if any(t.lower() in line.lower() for t in terms):
                hits.append((i,line[:800]))
                if len(hits)>=8: break
        if hits:
            print(' SHEET',ws.title)
            for h in hits: print('  ',h)
PY"

